css:
@page {
    size: A4;
    margin: 1cm;
}
.expense-voucher {
    font-size: 12px;
}
.pending-banner {
    text-align: center;
    font-weight: bold;
    padding: 10px;
    margin-bottom: 15px;
    border: 2px solid #000;
}

.voucher-header {
    text-align: center;
    margin-bottom: 20px;
}
.voucher-header h1 {
    margin-bottom: 5px;
}
.claim-details {
    margin-bottom: 20px;
}
.details-table {
    width: 100%;
    
}
.details-table td {
    padding: 7px;
    border: 1px solid #ccc;
}
.expense-lines {
    width: 100%;
}
.expense-lines th,
.expense-lines td {
    border: 1px solid #ccc;
    padding: 7px;
}
.expense-lines th {
    font-weight: bold;
    text-align: left;
}
.total-section {
    margin-top: 20px;
    text-align: right;
    font-weight: bold;
}
.total-label {
    font-size: 16px;
}
.total-amount {
    font-size: 22px;
    font-weight: bold;
    margin-top: 5px;
}
.print-summary {
    margin-top: 25px;
    font-size: 11px;
}
.approval-section {
    margin-top: 20px;
}
